<?php namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\Post; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Support\Facades\Storage; class PostController extends Controller { public function index() { \ = Post::latest()->paginate(10); return view('admin.posts.index', compact('posts')); } public function create() { return view('admin.posts.create'); } public function store(Request \) { \ = \->validate(['title' => 'required', 'content' => 'required']); \ = new Post(\); \->user_id = auth()->id(); if (\->hasFile('featured_image')) { \->featured_image = \->file('featured_image')->store('posts', 'public'); } \->is_published = \->has('is_published'); \->published_at = \->is_published ? now() : null; \->save(); return redirect()->route('admin.posts.index'); } public function edit(Post \) { return view('admin.posts.edit', compact('post')); } public function update(Request \, Post \) { \ = \->validate(['title' => 'required', 'content' => 'required']); \->fill(\); if (\->hasFile('featured_image')) { if (\->featured_image) Storage::disk('public')->delete(\->featured_image); \->featured_image = \->file('featured_image')->store('posts', 'public'); } \->is_published = \->has('is_published'); \->published_at = \->is_published && !\->published_at ? now() : \->published_at; \->save(); return redirect()->route('admin.posts.index'); } public function destroy(Post \) { if (\->featured_image) Storage::disk('public')->delete(\->featured_image); \->delete(); return redirect()->route('admin.posts.index'); } }